#include <meguviz/timeline.h>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
int main(int argc,char **argv){bool delayed=argc>1&&std::string(argv[1])=="--delayed";MgmPlannerConfig c{};c.header=MGC_HEADER_INIT(MgmPlannerConfig);c.target_fps=60;c.frame_window=12;c.max_clock_age_ns=250000000;c.max_clock_uncertainty_us=2000;c.original_tolerance_us=0;if(delayed){c.presentation_delay_ns=150000000;c.max_lead_ns=100000000;c.min_lead_ns=32000000;c.phase_lock=1;c.original_tolerance_us=1000;}MgmPlanner *p=nullptr;if(mgm_planner_create(&c,&p))return 1;MgmEpoch epoch{1,1,1,1,1};MgmOfferResult o{};o.header=MGC_HEADER_INIT(MgmOfferResult);uint64_t generation;if(mgm_planner_begin(p,&epoch,&generation,&o))return 2;MgmClockSnapshot clock{};clock.header=MGC_HEADER_INIT(MgmClockSnapshot);clock.speed=1;clock.discontinuity=1;clock.media_us=delayed?200000:0;uint32_t state;if(mgm_planner_clock(p,generation,&clock,&state,&o))return 3;for(uint64_t i=0;i<10;++i)if(mgm_planner_offer(p,generation,i,int64_t(i)*100000/3,&o))return 4;
    std::cout<<std::fixed<<std::setprecision(12);for(int tick=0;tick<12;++tick){int64_t now=int64_t(tick)*1000000000/60;MgmProposal proposal{};proposal.header=MGC_HEADER_INIT(MgmProposal);if(mgm_planner_plan(p,generation,now,&proposal))return 5;if(proposal.waiting_reason)std::cout<<"W "<<proposal.waiting_reason<<" "<<proposal.due_ns<<" "<<proposal.media_us<<"\n";else{std::cout<<"R "<<proposal.due_ns<<" "<<proposal.media_us<<" "<<proposal.before_id<<" "<<proposal.after_id<<" "<<proposal.alpha<<" "<<proposal.mode<<"\n";if(mgm_planner_commit(p,&proposal,now))return 6;}}mgm_planner_release(p);return 0;}
